import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

path = "budget.xlsx"
with zipfile.ZipFile(path) as z:
    names = z.namelist()
    print("FILES IN ARCHIVE:")
    for n in names:
        print("  ", n)
    print()

    shared_strings = []
    if "xl/sharedStrings.xml" in names:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared_strings.append(text)
    print("SHARED STRINGS (%d):" % len(shared_strings))
    for i, s in enumerate(shared_strings):
        print("  [%d] %r" % (i, s))
    print()

    wb = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = wb.find("m:sheets", NS)
    sheet_entries = []
    for sh in sheets.findall("m:sheet", NS):
        sheet_entries.append((sh.get("name"), sh.get("sheetId"), sh.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")))
    print("WORKBOOK SHEETS (name, sheetId, rId):")
    for e in sheet_entries:
        print("  ", e)
    print()

    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rid_to_target = {}
    for rel in rels:
        rid_to_target[rel.get("Id")] = rel.get("Target")
    print("WORKBOOK RELS:")
    for rid, target in rid_to_target.items():
        print("  ", rid, "->", target)
    print()

    def col_to_idx(col):
        idx = 0
        for ch in col:
            idx = idx * 26 + (ord(ch) - ord("A") + 1)
        return idx

    def idx_to_col(idx):
        s = ""
        while idx:
            idx, rem = divmod(idx - 1, 26)
            s = chr(ord("A") + rem) + s
        return s

    for rid, target in rid_to_target.items():
        if not target.startswith("worksheets/"):
            continue
        fname = "xl/" + target if not target.startswith("/") else target.lstrip("/")
        if fname not in names:
            continue
        root = ET.fromstring(z.read(fname))
        print("=== SHEET FILE: %s ===" % fname)
        for row in root.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row"):
            r = row.get("r")
            cells = []
            for c in row.findall("m:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("m:v", NS)
                isel = c.find("m:is", NS)
                raw = None
                if v is not None:
                    raw = v.text
                if t == "s" and raw is not None:
                    val = shared_strings[int(raw)]
                elif t == "inlineStr" and isel is not None:
                    val = "".join(x.text or "" for x in isel.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
                else:
                    val = raw
                cells.append("%s=%r" % (ref, val))
            print("  row %s: %s" % (r, " | ".join(cells)))
        print()

